function [rho] = density_scaled(h_m, scale)
%DENSITY_SCALED  The density at a geodetic height, times the activity factor; below the table's floor, the floor's density.
%   h_m: real[m] (passed in m)
%   scale: real[1] (passed a plain number)
%   returns rho: real[kg/m^3] (passed in kg/m^3)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rho = 0;
    h = (h_m / 1000);
    [h0, rho0, hs] = asils.models.env.atmosphere(h_m);
    if (h < 0)
        rho = (rho0 * scale);
    else
        rho = ((scale * rho0) * exp(((-((h - (h0 / 1000)))) / (hs / 1000))));
    end
end
